config:
{
  "models": {
    "mode": "merge",
    "providers": {
      "anthropic": {
        "baseUrl": "${HE_MODEL_BASE_URL}",
        "apiKey": "${HE_MODEL_API_KEY}",
        "api": "anthropic-messages",
        "models": [
          {
            "id": "claude-sonnet-5-5",
            "name": "Claude Sonnet 5.5",
            "reasoning": true,
            "input": [
              "text"
            ],
            "contextWindow": 200000,
            "maxTokens": 16384,
            "cost": {
              "input": 2,
              "output": 10,
              "cacheRead": 0.2,
              "cacheWrite": 2.5
            }
          }
        ]
      }
    }
  },
  "agents": {
    "defaults": {
      "model": {
        "primary": "anthropic/claude-sonnet-5-5"
      },
      "workspace": "/workspace",
      "skipBootstrap": true
    }
  },
  "mcp": {
    "servers": {
      "world": {
        "url": "http://127.0.0.1:9/mcp",
        "transport": "streamable-http",
        "headers": {
          "Authorization": "Bearer world-token-golden"
        },
        "connectionTimeoutMs": 30000,
        "requestTimeoutMs": 120000
      }
    }
  },
  "meta": {
    "migrations": {
      "modelPolicyAllowlist": true,
      "utilityModelSeparation": true
    },
    "lastTouchedVersion": "2026.10.6"
  }
}
